{{define "tasks-page"}}
<section class="workspace-page tasks-page"{{if not .Tasks.Configurations}} data-execution-list{{end}}>
<div class="control-list-heading"><h1>{{if .Tasks.Configurations}}{{tr "Configurations"}}{{else}}{{tr "Execution records"}}{{end}}</h1></div>

<form class="control-search control-list-search" method="get" action="{{if .Tasks.Configurations}}/tasks/configurations{{else}}/tasks{{end}}">{{if not .Tasks.Configurations}}<input type="hidden" name="view" value="{{.Tasks.Query.View}}">{{if .Tasks.Query.NeedsMe}}<input type="hidden" name="needs_me" value="1">{{end}}{{end}}{{template "icon-search"}}<label class="sr-only" for="task-search">{{tr "Find a task"}}</label><input id="task-search" type="search" name="q" value="{{.Tasks.Query.Query}}" placeholder="{{tr "Find a task by title or goal"}}"><button type="submit" class="control-icon-button" aria-label="{{tr "Search"}}">{{template "icon-arrow-right"}}</button></form>
<div class="control-list-toolbar task-list-toolbar">

{{if not .Tasks.Configurations}}
<div data-task-filters><details class="control-disclosure" data-task-filter-fallback><summary>{{template "icon-filter"}}{{tr "Filters"}}</summary><form class="control-disclosure-panel" method="get" action="/tasks"><input type="hidden" name="q" value="{{.Tasks.Query.Query}}"><label>{{tr "Status"}}<select name="view"><option value="all" {{if or (eq .Tasks.Query.View "all") (eq .Tasks.Query.View "attention")}}selected{{end}}>{{tr "All statuses"}}</option><option value="open" {{if eq .Tasks.Query.View "open"}}selected{{end}}>{{tr "In progress"}}</option><option value="closed" {{if eq .Tasks.Query.View "closed"}}selected{{end}}>{{tr "Finished"}}</option></select></label><label class="check"><input type="checkbox" name="needs_me" value="1" {{if or .Tasks.Query.NeedsMe (eq .Tasks.Query.View "attention")}}checked{{end}}>{{tr "Needs me"}}</label><button class="secondary">{{tr "Apply filters"}}</button></form></details><span data-task-filter-mount></span></div>
{{end}}

{{if .Tasks.Configurations}}<a class="button secondary" href="/tasks/schedules/new">{{tr "Create schedule"}}</a>{{end}}
</div>
<div id="ongoing-work">{{template "tasks-list" .}}</div></section>
{{end}}
{{define "tasks-list"}}
{{$recordCount := 0}}{{if .Tasks.Configurations}}{{$recordCount = len .Tasks.Scheduled}}{{range .Tasks.List.Items}}{{if not .Schedule}}{{$recordCount = add $recordCount 1}}{{end}}{{end}}{{else}}{{$recordCount = len .Tasks.Executions.Items}}{{end}}
{{if .Tasks.SchedulesUnavailable}}<p class="field-help" role="status">{{tr "Schedules are temporarily unavailable."}}</p>{{end}}
<div class="task-table-scroll" role="region" aria-label="{{if .Tasks.Configurations}}{{tr "Configurations"}}{{else}}{{tr "Execution records"}}{{end}}" tabindex="0">
<table class="task-table control-list-table"><thead><tr><th scope="col">{{tr "Title"}}</th><th scope="col">{{tr "Type"}}</th><th scope="col">{{tr "Status"}}</th><th scope="col">{{tr "Created"}}</th><th scope="col">{{tr "Updated"}}</th></tr></thead><tbody>
{{if .Tasks.Configurations}}
{{range .Tasks.Scheduled}}<tr data-live-key="schedule:{{.Ref}}"><td>{{if .Restricted}}{{tr "Schedule details unavailable"}}{{else}}<a class="task-list-title" href="/tasks/schedules/{{.Ref}}" title="{{taskTitle .Instruction}}">{{taskTitle .Instruction}}</a>{{end}}</td><td>{{if eq .Type "at"}}{{tr "One-time task"}}{{else}}{{tr "Scheduled work"}}{{end}}</td><td><span class="status-pill control-status-badge" data-status="{{if .Enabled}}enabled{{else}}disabled{{end}}">{{if .Enabled}}{{tr "Enabled"}}{{else}}{{tr "Disabled"}}{{end}}</span></td><td>{{humanTime .CreatedAt}}</td><td>{{humanTime .UpdatedAt}}</td></tr>{{end}}
{{range .Tasks.List.Items}}{{if not .Schedule}}<tr data-live-key="task:{{.TaskRef}}"><td><a class="task-list-title" href="{{taskURL .TaskRef}}" title="{{.Title}}">{{.Title}}</a></td><td>{{if eq .CompletionPolicy "ongoing"}}{{tr "Ongoing task"}}{{else}}{{tr "One-time task"}}{{end}}</td><td><span class="status-pill control-status-badge" data-status="{{.Status}}">{{tr .Status}}</span></td><td>{{humanTime .CreatedAt}}</td><td>{{humanTime .UpdatedAt}}</td></tr>{{end}}{{end}}
{{if eq $recordCount 0}}<tr><td colspan="5" class="task-table-empty">{{tr "No matching tasks"}}</td></tr>{{end}}
{{else}}
{{range .Tasks.Executions.Items}}<tr data-execution-row data-task-ref="{{.TaskRef}}" id="execution-{{.ID}}" data-live-key="execution:{{.ID}}"><td><a class="task-list-title" data-execution-open href="{{executionURL .ID}}" title="{{.Title}}">{{.Title}}</a></td><td>{{if eq .CompletionPolicy "ongoing"}}{{tr "Ongoing task"}}{{else}}{{tr "One-time task"}}{{end}}</td><td><span class="task-row-state status-pill control-status-badge" data-status="{{.Status}}">{{tr .Status}}</span>{{if .NeedsAttention}}<span class="sr-only">{{tr "Needs you"}}</span>{{end}}</td><td>{{humanTime .CreatedAt}}</td><td>{{humanTime .UpdatedAt}}</td></tr>{{else}}<tr><td colspan="5" class="task-table-empty">{{if eq .Tasks.Query.View "attention"}}{{tr "Nothing needs your attention"}}{{else if eq .Tasks.Query.View "closed"}}{{tr "No finished tasks yet"}}{{else}}{{tr "No matching tasks"}}{{end}}</td></tr>{{end}}
{{end}}
</tbody></table></div>
<div class="control-list-footer"><span>{{$recordCount}} {{tr "records on this page"}}</span>{{if .Tasks.Configurations}}{{if .Tasks.List.Next}}<a class="button secondary" href="{{taskListURL .Tasks "cursor" .Tasks.List.Next}}">{{tr "Older tasks →"}}</a>{{end}}{{else}}{{if .Tasks.Executions.Next}}<a class="button secondary" href="{{taskListURL .Tasks "cursor" .Tasks.Executions.Next}}">{{tr "Older tasks →"}}</a>{{end}}{{end}}</div>
{{end}}
{{define "execution-page"}}
<section id="execution-detail" class="workspace-page task-page execution-page" data-execution-id="{{.Tasks.Execution.ID}}">
<a class="back-link" href="/tasks">← {{tr "Execution records"}}</a>
<div id="execution-header">{{template "execution-header" $}}</div>
<div class="execution-main">
<div id="execution-progress">{{template "execution-progress" $}}</div>
<section class="execution-result" aria-label="{{tr "Execution result"}}"><h2 class="sr-only">{{tr "Execution result"}}</h2><div id="task-messages">{{template "execution-result" $}}</div></section>
</div>
<div id="execution-side" class="execution-side">{{template "execution-side" $}}</div>
</section>
{{end}}
{{define "execution-header"}}{{with .Tasks.Execution}}<header class="execution-heading">
<h1>{{.Title}}</h1>
<div class="execution-summary"><span class="status-pill control-status-badge" data-status="{{.Status}}">{{tr .Status}}</span><span>{{if eq .CompletionPolicy "ongoing"}}{{tr "Ongoing task"}}{{else}}{{tr "One-time task"}}{{end}}</span><span>{{tr "Execution round"}} {{.Epoch}}</span>{{humanTime .CreatedAt}}<a class="text-link execution-trace" href="/developer/observability/{{.ID}}">{{tr "View trace →"}}</a></div>
{{if .NeedsAttention}}<nav class="execution-actions" aria-label="{{tr "Execution actions"}}"><a class="button secondary" href="{{taskURL .TaskRef}}">{{tr "Needs your attention"}}</a></nav>{{end}}
</header>{{end}}{{end}}
{{define "execution-side"}}{{with .Tasks.Execution}}
{{if or (and .Description (ne .Description .Title)) .Instructions}}<details class="execution-instructions" data-live-key="instructions"><summary>{{tr "Task instructions"}}</summary>{{if and .Description (ne .Description .Title)}}<div class="semantic">{{.Description}}</div>{{end}}{{if .Instructions}}<h3>{{tr "Accepted instructions"}}</h3><ol>{{range .Instructions}}<li><div class="semantic">{{.Text}}</div>{{humanTime .At}}</li>{{end}}</ol>{{end}}</details>{{end}}
{{if gt (len .RecentRuns) 1}}<details class="execution-history" data-live-key="history"><summary>{{tr "Recent runs"}} <span class="execution-count">{{len .RecentRuns}}</span></summary><ol>{{range .RecentRuns}}<li><a href="{{executionURL .ID}}" {{if eq .ID $.Tasks.Execution.ID}}aria-current="page"{{end}}><span>{{tr "Execution round"}} {{.Epoch}}</span><span class="status-pill control-status-badge" data-status="{{.Status}}">{{tr .Status}}</span>{{humanTime .CreatedAt}}</a></li>{{end}}</ol></details>{{end}}
<details class="execution-metadata" data-live-key="metadata"><summary>{{tr "Run details"}}</summary><dl class="execution-facts"><div><dt>{{tr "Created"}}</dt><dd>{{humanTime .CreatedAt}}</dd></div><div><dt>{{tr "Updated"}}</dt><dd>{{humanTime .UpdatedAt}}</dd></div><div><dt>{{tr "Trace ID"}}</dt><dd>{{workbenchIdentifier (identifier "" .ID "")}}</dd></div></dl><nav class="execution-actions" aria-label="{{tr "Execution actions"}}"><a class="text-link" href="{{taskURL .TaskRef}}">{{tr "Task configuration →"}}</a><a class="control-icon-button" data-execution-refresh href="{{executionURL .ID}}" aria-label="{{tr "Refresh"}}" title="{{tr "Refresh"}}">{{template "icon-refresh"}}</a></nav></details>
{{end}}{{end}}
{{define "execution-progress"}}{{with .Tasks.Execution}}{{if and .ProgressSummary (not $.Tasks.Messages)}}<section class="execution-progress"><h2>{{tr "Latest progress"}}</h2><p>{{.ProgressSummary}}</p></section>{{end}}{{end}}{{end}}
{{define "execution-result"}}{{if .Tasks.Messages}}{{template "task-messages" $}}{{else}}{{with .Tasks.Execution}}<p class="execution-empty" role="status">{{if eq .Status "running"}}{{tr "Work is in progress. Updates will appear here when delivered."}}{{else if eq .Status "queued"}}{{tr "This run is queued. Results will appear here when delivered."}}{{else if eq .Status "waiting"}}{{tr "This run is waiting. Open task configuration to review any required action."}}{{else if eq .Status "failed"}}{{tr "This run did not finish. Open task configuration to review the task."}}{{else if eq .Status "cancelled"}}{{tr "This run was cancelled. No result has been delivered."}}{{else}}{{tr "No result has been delivered for this run yet."}}{{end}}</p>{{end}}{{end}}{{end}}

{{define "tasks-navigation"}}
{{$configuration := taskConfigurationPage .Path}}
<div class="section-navigation-heading"><span>{{tr "Tasks"}}</span></div>
<nav class="section-navigation" aria-label="{{tr "Task sections"}}">
 <a href="/tasks" {{if not $configuration}}aria-current="page"{{end}}>{{template "icon-progress"}}<span>{{tr "Execution records"}}</span></a>
 <a href="/tasks/configurations" {{if $configuration}}aria-current="page"{{end}}>{{template "icon-configuration"}}<span>{{tr "Configurations"}}</span></a>
</nav>
{{end}}

{{define "task-page"}}
<section class="workspace-page task-page">
 <div id="task-header">{{template "task-header" .}}</div>
 <div class="task-detail-grid"><div>
  <div id="task-feedback">{{template "task-feedback" .}}</div>
  <div id="task-feedback-status" class="feedback-status" role="status" aria-live="polite">{{if .FeedbackDraft}}<p>{{tr "Your response was not saved. Review the current request before trying again."}}</p><label for="feedback-kept-draft">{{tr "Your saved draft"}}</label><textarea id="feedback-kept-draft" readonly rows="3">{{.FeedbackDraft}}</textarea>{{end}}</div>
  <div id="task-decisions">{{template "task-decisions" .}}</div>
  {{with .Tasks.Detail}}{{if and .GoalSummary (ne .GoalSummary .Title)}}<section class="task-objective"><h2>{{tr "Planned objective"}}</h2><div class="semantic">{{.GoalSummary}}</div></section>{{end}}{{end}}
  <div id="task-progress">{{template "task-progress" .}}</div>
  {{if .Tasks.Artifacts}}<section class="task-results"><h2>{{tr "Delivered files"}}</h2><div class="attachment-list">{{range .Tasks.Artifacts}}<a class="attachment-link" href="/artifact?ref={{.Ref}}">↓ {{.Name}}</a>{{end}}</div></section>{{end}}
  <section class="task-results"><h2>{{tr "Related updates from Ghost"}}</h2><div id="task-messages">{{template "task-messages" .}}</div></section>
 </div><div class="task-side">
  {{with .Tasks.Detail}}<section class="panel"><h2>{{tr "Adjust this task"}}</h2><a class="button {{if $.Tasks.Approvals}}secondary{{end}}" href="/?task={{.TaskRef}}">{{tr "Continue this task →"}}</a>{{if .SourceSequence}}<p><a href="{{conversationURL .SourceSequence}}">{{tr "View original request"}}</a></p>{{end}}</section>{{end}}
  <details class="panel task-history"><summary>{{tr "Request & milestone history"}}</summary><div id="task-milestones">{{template "task-milestones" .}}</div></details>
  {{with .Tasks.Detail}}<details class="technical-details"><summary>{{tr "Technical details"}}</summary><p>{{tr "Task reference:"}} {{workbenchIdentifier (identifier "" .TaskRef "")}} {{tr "· epoch"}} {{.Epoch}}</p><a href="/developer/observability?task={{.TaskRef}}">{{tr "Inspect execution epochs →"}}</a></details>{{end}}
 </div></div>

</section>
{{end}}
{{define "task-header"}}{{with .Tasks.Detail}}<div class="page-heading" data-live-key="heading"><div><h1>{{.Title}}</h1></div><span class="status-pill state" data-status="{{.Status}}">{{tr .Status}}</span></div>{{end}}{{end}}
{{define "task-decisions"}}{{if .Tasks.Approvals}}<h2 data-live-key="heading">{{tr "Your decision is needed"}}</h2>{{range .Tasks.Approvals}}<div data-live-key="approval:{{.ID}}">{{workbenchApproval .}}</div>{{end}}{{end}}{{end}}
{{define "task-progress"}}{{with .Tasks.Detail}}<section class="task-configuration" data-live-key="configuration"><h2 aria-label="{{tr "Execution rule"}}">{{template "icon-configuration"}}{{tr "Execution rule"}}{{if eq .CompletionPolicy "ongoing"}}{{workbenchHelp (help "task-rule-help" (tr "Execution rule") (printf "%s %s" (tr "The original objective and completion rule are fixed for this task. Create a new task to use a different completion rule.") (tr "Finishing a work session keeps this task open. Further work needs a new instruction or a configured trigger.")))}}{{else if eq .CompletionPolicy "once"}}{{workbenchHelp (help "task-rule-help" (tr "Execution rule") (printf "%s %s" (tr "The original objective and completion rule are fixed for this task. Create a new task to use a different completion rule.") (tr "Completes when its work finishes successfully, unless Ghost explicitly continues it.")))}}{{else}}{{workbenchHelp (help "task-rule-help" (tr "Execution rule") (tr "The original objective and completion rule are fixed for this task. Create a new task to use a different completion rule."))}}{{end}}</h2><p class="task-rule-name">{{if eq .CompletionPolicy "ongoing"}}{{tr "Ongoing task"}}{{else if eq .CompletionPolicy "once"}}{{tr "One-time task"}}{{else}}{{tr "Completion rule unavailable"}}{{end}}</p>
{{with .Schedule}}{{if .Restricted}}<p class="field-help">{{tr "Schedule details are unavailable because the original scheduling context was revoked."}}</p>{{else}}<div class="control-help-line"><a class="text-link" href="/tasks/schedules/{{.Ref}}">{{tr "Edit schedule"}}</a>{{workbenchHelp (help "task-schedule-help" (tr "Schedule") (tr "A scheduled occurrence is a trigger, not a guaranteed start time. Current task state and available resources still apply."))}}</div><dl class="task-rule-facts"><div><dt>{{tr "Schedule"}}</dt><dd>{{if .Enabled}}{{tr "Enabled"}}{{else}}{{tr "Disabled"}}{{end}} · {{scheduleFrequency .}}</dd></div><div><dt>{{if eq .Type "cron"}}{{tr "Cron expression"}}{{else}}{{tr "Scheduled time"}}{{end}}</dt><dd>{{if eq .Type "cron"}}<code>{{.Spec}}</code>{{else}}{{scheduleTime .}}{{end}}</dd></div><div><dt>{{tr "Time zone"}}</dt><dd>{{.Timezone}}</dd></div><div><dt>{{tr "Next scheduled occurrence"}}</dt><dd>{{if not .Enabled}}{{tr "Schedule disabled"}}{{else if .NextAt}}{{humanTime .NextAt}}{{else}}{{tr "No further scheduled occurrence"}}{{end}}</dd></div>{{if .Below}}<div><dt>{{tr "Notify when entering below"}}</dt><dd>{{.Below}}</dd></div>{{end}}</dl><details class="technical-details task-scheduled-instructions"><summary>{{tr "Scheduled instructions"}}</summary><div class="semantic">{{.Instruction}}</div></details>{{end}}{{else}}<p class="field-help">{{tr "No automatic schedule is configured for this task."}}</p><a class="text-link" href="/tasks/schedules/new">{{tr "Create a separate schedule →"}}</a>{{workbenchHelp (help "task-new-schedule-help" (tr "Create schedule") (tr "A new schedule is a separate arrangement; it does not change this task or its current work."))}}{{end}}</section>
{{if .Instructions}}<section class="task-instructions" data-live-key="instructions"><h2 aria-label="{{tr "Accepted instructions"}}">{{tr "Accepted instructions"}}{{if .MoreInstructions}}<span class="status-pill">{{len .Instructions}}+</span>{{workbenchHelp (help "task-instructions-help" (tr "Accepted instructions") (tr "Showing the 20 most recent instructions. Earlier additions remain in request and milestone history."))}}{{end}}</h2><ol>{{range .Instructions}}<li><div class="semantic">{{.Text}}</div>{{humanTime .At}}</li>{{end}}</ol></section>{{end}}
<section class="task-current-progress" data-live-key="progress"><h2>{{tr "Latest progress"}}</h2><p>{{tr .Stage}}</p>{{if .ProgressSummary}}<p>{{.ProgressSummary}}</p>{{end}}{{with .Progress}}{{if .Children}}<h3>{{tr "Delegated work ·"}} {{.Children}} {{tr "total"}}</h3><dl class="facts"><div><dt>{{tr "Completed / failed"}}</dt><dd>{{.Succeeded}} / {{.Failed}}</dd></div><div><dt>{{tr "Running / queued / waiting"}}</dt><dd>{{.Running}} / {{.Queued}} / {{.Waiting}}</dd></div></dl>{{end}}{{end}}{{tr "Updated"}} {{humanTime .UpdatedAt}}</section>{{end}}{{end}}
{{define "task-messages"}}{{range .Tasks.Messages}}<div class="task-delivery" data-live-key="message:{{.Sequence}}"><div data-ui-spec="{{.Projection.Spec}}" data-ui-fallback="{{.Projection.Fallback}}">{{.Projection.HTML}}</div><a class="text-link" href="{{conversationURL .Sequence}}">{{tr "Open in conversation →"}}</a></div>{{else}}<p class="muted" data-live-key="empty">{{tr "No related updates yet."}}</p>{{end}}{{end}}
{{define "task-milestones"}}{{with .Tasks.Detail}}<ol>{{range .History}}<li data-live-key="milestone:{{.ID}}"><strong>{{tr (historyLabel .Kind)}}</strong>{{humanTime .At}}{{if .Text}}<div class="semantic">{{.Text}}</div>{{end}}</li>{{else}}<li>{{tr "No recorded milestones yet."}}</li>{{end}}</ol>{{if .HistoryNext}}<a href="{{taskURL .TaskRef}}?history={{.HistoryNext}}">{{tr "Older milestones →"}}</a>{{end}}{{end}}{{end}}

{{define "tasks-attention"}}{{with .Attention}}
{{if or .Count .Unavailable .More}}<div class="attention-heading" data-live-key="attention-heading"><h2 aria-label="{{tr "Needs your attention"}}">{{tr "Needs your attention"}}{{if .More}}{{workbenchHelp (help "attention-count-help" (tr "Needs your attention") (tr "This is a page of current items, not a total count."))}}{{end}} {{if .Count}}<span class="status-pill">{{.Count}}{{if .More}}+{{end}}</span>{{end}}</h2></div>{{end}}
{{if .Unavailable}}<p class="field-help" role="status" data-live-key="attention-unavailable">{{tr "Some attention items are temporarily unavailable. The items below are still current."}}</p>{{end}}
{{range .Feedbacks}}<article class="attention-row" data-live-key="feedback:{{.Ref}}"><div><h3>{{.Prompt}}</h3><p>{{.TaskTitle}}</p>{{if eq .Kind "review"}}<div class="attachment-list">{{range .Artifacts}}<a class="attachment-link" href="/artifact?ref={{.Ref}}">{{.Name}}</a>{{end}}</div>{{end}}</div><a class="button secondary" href="{{taskURL .TaskRef}}#{{.Ref}}">{{if eq .Kind "review"}}{{tr "Review result"}}{{else}}{{tr "Answer question"}}{{end}}</a></article>{{end}}
{{range .Approvals}}<div data-live-key="attention-approval:{{.ID}}">{{workbenchApproval .}}</div>{{end}}
{{range .Issues}}<article class="attention-row" data-live-key="attention-issue:{{.Key}}"><div><h3>{{.Title}}</h3><p>{{tr .Description}}</p></div><a class="button secondary" href="{{.URL}}">{{tr .Action}}</a></article>{{end}}
{{if .More}}<div class="field-help" data-live-key="attention-more"><div class="actions">{{if .Next}}<a href="{{.Next}}">{{tr "More questions and reviews"}}</a>{{end}}{{if .ApprovalNext}}<a href="{{.ApprovalNext}}">{{tr "More approvals in conversation"}}</a>{{end}}{{if .TasksNext}}<a href="{{.TasksNext}}">{{tr "Browse tasks needing attention"}}</a>{{end}}</div></div>{{end}}
{{end}}{{end}}

{{define "task-feedback"}}{{with .Attention}}{{range .Feedbacks}}<section class="task-feedback-request" id="{{.Ref}}" data-live-key="feedback:{{.Ref}}" tabindex="-1" aria-labelledby="heading-{{.Ref}}"><h2 id="heading-{{.Ref}}">{{if eq .Kind "review"}}{{tr "Review this result"}}{{else}}{{tr "Ghost has a question"}}{{end}}</h2><p class="feedback-prompt">{{.Prompt}}</p>
{{if .Artifacts}}<div class="attachment-list">{{range .Artifacts}}<a class="attachment-link" href="/artifact?ref={{.Ref}}">{{.Name}}</a>{{end}}</div>{{end}}
{{if .SourceSequence}}<p class="field-help"><a href="{{conversationURL .SourceSequence}}">{{tr "View related message"}}</a></p>{{end}}
<form method="post" action="/task/feedback" class="task-feedback-form"><input type="hidden" name="source_id" value="{{.Ref}}"><input type="hidden" name="feedback_ref" value="{{.Ref}}"><input type="hidden" name="return_to" value="{{taskURL .TaskRef}}"><label for="answer-{{.Ref}}"><span class="control-field-label">{{if eq .Kind "review"}}{{tr "Your review feedback"}}{{else}}{{tr "Your answer"}}{{end}}{{if eq .Kind "review"}}{{workbenchHelp (help (printf "feedback-help-%s" .Ref) (tr "Your review feedback") (tr "Reviewing a result does not approve external actions. Ghost will consider your feedback before continuing."))}}{{else}}{{workbenchHelp (help (printf "feedback-help-%s" .Ref) (tr "Your answer") (tr "Your answer goes to Ghost in the conversation. It does not directly restart the task."))}}{{end}}</span></label><textarea aria-label="{{if eq .Kind "review"}}{{tr "Your review feedback"}}{{else}}{{tr "Your answer"}}{{end}}" id="answer-{{.Ref}}" name="answer" required maxlength="16384" rows="3" aria-describedby="feedback-help-{{.Ref}}">{{.Draft}}</textarea><button type="submit" {{if not (canSend $.Status)}}disabled{{end}}>{{if eq .Kind "review"}}{{tr "Send review feedback"}}{{else}}{{tr "Send answer"}}{{end}}</button><p class="field-help" data-feedback-model-needed {{if canSend $.Status}}hidden{{end}}>{{tr "Connect a ready model before sending. Your draft can stay here."}} <a href="/settings/models">{{tr "Open model settings"}}</a></p></form></section>{{end}}{{end}}{{end}}

{{define "conversation-page"}}
{{workbenchComputer}}{{workbenchWorkers}}
<section class="thread">
 <div id="conversation-messages">{{template "conversation" .}}</div>
 <div id="conversation-outgoing"></div>
 <div id="agent-processing" class="agent-processing" role="status" aria-label="{{tr "Ghost is working…"}}"><span class="typing-dots" aria-hidden="true"><i></i><i></i><i></i></span></div>
 <div id="conversation-ui-preview" hidden></div>
 <article id="conversation-draft" class="reply-draft" aria-label="{{tr "Draft reply from Ghost"}}" aria-busy="true" hidden><div class="reply-draft-label">{{tr "Draft reply"}}</div><div class="semantic" data-draft-text></div></article>
 <div id="conversation-approvals">{{template "approvals" .}}</div>
</section>
<footer class="conversation-footer"><form id="composer-model-form" method="post" action="/model/choose"><input type="hidden" name="consent" value="yes"><input type="hidden" name="config_version" value="{{.Status.ConfigVersion}}"><button type="submit" class="secondary model-native-submit">{{tr "Use model"}}</button></form>
<div id="composer-root" data-source-id="{{.SourceID}}">
 <form class="composer" action="/message" method="post" enctype="multipart/form-data">
  <input type="hidden" name="source_id" value="{{.SourceID}}">
  {{with .DraftTask}}<div class="task-context-chip"><input type="hidden" name="task_ref" value="{{.Ref}}"><span>{{tr "Regarding"}} <a href="{{taskURL .Ref}}">{{.Title}}</a></span><button class="plain-button" type="button" data-clear-task aria-label="{{tr "Clear task context"}}">×</button></div>{{end}}
  <label for="message" class="sr-only">{{tr "Message Ghost"}}</label>
  <textarea class="control-input-embedded" id="message" name="text" placeholder="{{tr "Describe what you have in mind…"}}" required rows="2" maxlength="16384">{{.Draft}}</textarea>
  <div class="composer-actions"><div class="attachment-controls"><label class="attachment-picker" title="{{tr "Attach a file"}}">{{template "icon-attach"}}<span class="sr-only">{{tr "Attach a file"}}</span><input type="file" name="file" aria-label="{{tr "Attach a file"}}"></label><span class="attachment-status" aria-live="polite"></span><button type="button" class="plain-button" data-remove-file hidden aria-label="{{tr "Remove attachment"}}">×</button></div><div class="composer-secondary-actions">{{$picker:=modelPickerView .ComposerModels .Language}}<div class="composer-model" data-composer-model data-model-picker="{{obsJSON .ComposerModels.Picker}}" data-reader-revision="{{.ComposerModels.ReaderRevision}}" data-current="{{.ComposerModels.Current}}" data-config-version="{{.ComposerModels.ConfigVersion}}"><label for="composer-model" class="sr-only">{{$picker.Label}}</label><select data-control-react id="composer-model" name="choice" form="composer-model-form" aria-label="{{$picker.Label}}">{{if not .ComposerModels.Current}}<option value="">{{$picker.PlaceholderLabel}}</option>{{end}}{{range .ComposerModels.Choices}}<option value="{{.Key}}" {{if eq $.ComposerModels.Current .Key}}selected{{end}}>{{.Label}}</option>{{end}}</select></div><button type="submit" class="send-button" aria-label="{{tr "Send message"}}" {{if not (canSend .Status)}}disabled{{end}}>{{template "icon-send"}}</button></div></div>
  <p id="composer-feedback" class="composer-feedback" role="status" aria-live="polite"></p>
 </form>
</div></footer><button type="button" id="new-messages" hidden>{{tr "Latest messages ↓"}}</button>
{{end}}
{{define "attention-summary"}}{{if and .Attention (or .Attention.Feedbacks .Attention.Issues .Attention.Unavailable .Attention.More)}}{{with .Attention}}<a class="button secondary attention-summary" title="{{tr "Open attention items in a new tab"}}" target="_blank" rel="noopener" aria-label="{{tr "Needs your attention"}} · {{.Count}}{{if .More}}+{{end}}" href="/tasks/attention">{{template "icon-attention"}}<span>{{tr "Needs your attention"}}</span>{{if .Count}}<strong>{{.Count}}{{if .More}}+{{end}}</strong>{{else}}<span>{{tr "Check current items"}}</span>{{end}}<span class="sr-only">{{tr "Opens in a new tab"}}</span></a>{{end}}{{else}}{{if .PendingCount}}<a class="button secondary attention-summary" data-pending-jump aria-label="{{tr "Needs your decision"}} · {{.PendingCount}}" href="/#approval-{{.FirstPending}}">{{template "icon-attention"}}<span>{{tr "Pending approval"}}</span><strong>{{.PendingCount}}</strong></a>{{end}}{{end}}{{end}}

{{define "conversation"}}
{{if not (canSend .Status)}}<div class="setup-callout" data-live-key="setup"><div>{{if eq .Status.Readiness "setup_required"}}<h1>{{tr "Setup required"}}</h1>{{else}}<h1>{{tr "Needs attention"}}</h1>{{end}}</div><a class="button secondary" href="/settings/models">{{tr "Set up Steward →"}}</a></div>{{end}}
{{if .Before}}<a data-live-key="earlier" class="back-link" href="/?before={{.Before}}">{{tr "Earlier messages"}}</a>{{end}}
{{$day := ""}}{{range .Messages}}{{if .CreatedAt}}<div class="message-date" data-live-key="date:{{.Sequence}}"{{if eq $day (messageDay .CreatedAt)}} hidden{{end}}>{{localTime .CreatedAt "date"}}</div>{{$day = messageDay .CreatedAt}}{{end}}<article class="message {{.Role}}{{if .Bubbles}} message-split{{end}}" id="message-{{.Sequence}}" data-live-key="message:{{.Sequence}}"{{if .ReplyKey}} data-reply-key="{{.ReplyKey}}"{{end}}{{if .ClientSource}} data-client-source="{{.ClientSource}}"{{end}}><span class="sr-only">{{if eq .Role "user"}}{{tr "You"}}{{else}}Ghost{{end}}</span>{{if .Approval}}{{workbenchApproval .Approval}}{{else if .Bubbles}}{{range .Bubbles}}<div class="message-bubble" data-ui-spec="{{.Spec}}" data-ui-fallback="{{.Fallback}}">{{.HTML}}</div>{{end}}{{else}}<div data-ui-spec="{{.Projection.Spec}}" data-ui-fallback="{{.Projection.Fallback}}">{{.Projection.HTML}}</div>{{end}}{{if .CreatedAt}}<span class="message-time">{{localTime .CreatedAt "message"}}</span>{{end}}</article>
{{else}}{{if canSend .Status}}<div class="welcome" data-live-key="welcome"><h1>{{tr "What would you like to work on?"}}</h1></div>{{end}}{{end}}
{{end}}
{{define "approvals"}}{{range .Approvals}}<div data-live-key="approval:{{.ID}}">{{workbenchApproval .}}</div>{{end}}{{end}}

{{define "schedule-editor-page"}}
<section class="workspace-page schedule-editor-page">
 {{with .Schedule}}
 <div class="page-heading"><div><h1 aria-label="{{if .Ref}}{{tr "Edit schedule"}}{{else}}{{tr "Create schedule"}}{{end}}"><span class="control-field-label">{{if .Ref}}{{tr "Edit schedule"}}{{else}}{{tr "Create schedule"}}{{end}}{{workbenchHelp (help "schedule-save-help" (tr "Schedule") (tr "Saving configures future triggers only. It does not run the task now or rewrite instructions for work already admitted."))}}</span></h1></div></div>
 <form class="schedule-editor" method="post" action="/schedule/configure">
  <input type="hidden" name="ref" value="{{.Ref}}"><input type="hidden" name="version" value="{{.Version}}"><input type="hidden" name="source_id" value="{{.Key}}"><input type="hidden" name="original_spec" value="{{.OriginalSpec}}"><input type="hidden" name="original_timezone" value="{{.OriginalTimezone}}">
  <div class="schedule-field"><label for="schedule-instruction">{{tr "Instructions"}}</label><textarea id="schedule-instruction" name="instruction" rows="4" maxlength="8192" required>{{.Instruction}}</textarea></div>
  <label class="schedule-enabled setting-switch"><input type="checkbox" role="switch" name="enabled" value="yes" {{if .Enabled}}checked{{end}} aria-label="{{tr "Schedule enabled"}}"><span class="control-field-label">{{tr "Schedule enabled"}}{{workbenchHelp (help "schedule-enabled-help" (tr "Schedule enabled") (tr "Disabling stops future triggers. Work already admitted keeps its frozen instructions; this does not pause or cancel the linked task."))}}</span></label>

  <div class="schedule-field"><label for="schedule-frequency">{{tr "Frequency"}}</label><select id="schedule-frequency" name="frequency"><option value="once" {{if eq .Frequency "once"}}selected{{end}}>{{tr "Once"}}</option><option value="daily" {{if eq .Frequency "daily"}}selected{{end}}>{{tr "Every day"}}</option><option value="weekdays" {{if eq .Frequency "weekdays"}}selected{{end}}>{{tr "Weekdays"}}</option><option value="weekly" {{if eq .Frequency "weekly"}}selected{{end}}>{{tr "Weekly"}}</option><option value="monthly" {{if eq .Frequency "monthly"}}selected{{end}}>{{tr "Monthly"}}</option><option value="custom" {{if eq .Frequency "custom"}}selected{{end}}>{{tr "Custom cron"}}</option></select></div>
  <div data-schedule-fields="once"><label>{{tr "Date"}}<input type="date" name="date" value="{{.Date}}"></label></div>
  <div data-schedule-fields="clock"><label>{{tr "Local time"}}<input type="time" name="time" value="{{.Time}}" step="60"></label></div>
  <div data-schedule-fields="weekly"><label>{{tr "Day of week"}}<select name="weekday"><option value="1" {{if eq .Weekday "1"}}selected{{end}}>{{tr "Monday"}}</option><option value="2" {{if eq .Weekday "2"}}selected{{end}}>{{tr "Tuesday"}}</option><option value="3" {{if eq .Weekday "3"}}selected{{end}}>{{tr "Wednesday"}}</option><option value="4" {{if eq .Weekday "4"}}selected{{end}}>{{tr "Thursday"}}</option><option value="5" {{if eq .Weekday "5"}}selected{{end}}>{{tr "Friday"}}</option><option value="6" {{if eq .Weekday "6"}}selected{{end}}>{{tr "Saturday"}}</option><option value="0" {{if eq .Weekday "0"}}selected{{end}}>{{tr "Sunday"}}</option></select></label></div>
  <div data-schedule-fields="monthly"><label><span class="control-field-label">{{tr "Day of month"}}{{workbenchHelp (help "schedule-month-help" (tr "Day of month") (tr "Months without this date are skipped."))}}</span><input type="number" name="day" min="1" max="31" value="{{.Day}}" aria-label="{{tr "Day of month"}}"></label></div>
  <div data-schedule-fields="custom"><label><span class="control-field-label">{{tr "Cron expression"}}{{workbenchHelp (help "schedule-cron-help" (tr "Cron expression") (tr "Five fields: minute, hour, day of month, month, weekday. Uses the time zone below."))}}</span><input type="text" name="cron" value="{{.Cron}}" maxlength="256" placeholder="0 8 * * *" spellcheck="false" aria-label="{{tr "Cron expression"}}"></label></div>
  <label><span class="control-field-label">{{tr "Time zone"}}{{workbenchHelp (help "schedule-zone-help" (tr "Time zone") (tr "Use an IANA time zone. One-time times during a clock change must identify one unambiguous instant."))}}</span><input type="text" name="timezone" value="{{.Timezone}}" maxlength="128" placeholder="Asia/Shanghai" required spellcheck="false" aria-label="{{tr "Time zone"}}"></label>

  <details class="technical-details"><summary>{{tr "Advanced"}}</summary><label><span class="control-field-label">{{tr "Notify when entering below"}}{{workbenchHelp (help "schedule-threshold-help" (tr "Notify when entering below") (tr "Optional integer threshold. Leave blank for ordinary scheduling; zero is a valid threshold. Editing a schedule stops observations from older schedule versions from notifying."))}}</span><input type="number" name="threshold" min="0" max="1000000000000" value="{{.Threshold}}" aria-label="{{tr "Notify when entering below"}}"></label></details>

  <div class="actions"><button type="submit">{{tr "Save schedule"}}</button><a class="button secondary" href="/tasks">{{tr "Cancel"}}</a>{{if .Ref}}<a class="text-link" href="/tasks/schedules/{{.Ref}}">{{tr "Reload saved schedule"}}</a>{{end}}</div>
 </form>
 {{end}}
</section>
{{end}}

stylesheet.source:
.task-row{align-items:flex-start}
.task-row-title{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.task-row-title strong{font-size:15px}
.attention-mark{font-size:10px;font-weight:600;color:var(--warning);background:var(--warning-surface);border-radius:5px;padding:2px 7px}
.task-row p{font-size:13px;margin:6px 0 0}
.task-summary{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;overflow-wrap:anywhere}
.task-history time{display:block;font-size:11px;color:var(--muted-foreground);margin-top:10px}
.task-detail-grid{display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:22px}
.task-detail-grid>div{min-width:0}
.task-side .panel{padding:20px}
.task-side .button{width:100%}
.task-page{container:task-layout / inline-size}
.task-delivery+.task-delivery{margin-top:22px;padding-top:22px;border-top:1px solid var(--border)}
.task-delivery .text-link{display:inline-block;margin-top:14px}
.task-history summary{font-size:13px;font-weight:550;color:var(--foreground)}
.task-history ol{list-style:none;padding:0;margin:18px 0 0}
.task-history li{font-size:12px;border-left:1px solid var(--border);padding:0 0 18px 14px}
.task-history li .semantic{margin-top:8px;font-size:12px;max-height:140px;overflow:auto}
@media(max-width:1000px){.task-detail-grid{grid-template-columns:minmax(0,1fr) 250px}}
@media(max-width:800px){.task-detail-grid{grid-template-columns:1fr}
.task-side{display:grid;grid-template-columns:1fr}}
@container task-layout (max-width:760px){.task-detail-grid{grid-template-columns:minmax(0,1fr)}
.task-side{display:grid;grid-template-columns:minmax(0,1fr)}}
@media(max-width:700px){.task-row-title strong{font-size:14px}}
.attention-mark,.task-history time{font-size:12px}
@media(min-width:1280px){.workspace-panel-open:not(.workspace-panel-expanded) .conversation-footer{right:460px}
.workspace-panel-open:not(.workspace-panel-expanded) #new-messages{right:480px}}
.tasks-page{max-width:none;margin:0;padding:0}
.task-list-toolbar{flex-wrap:wrap;justify-content:flex-start;gap:8px}
.tasks-page #ongoing-work{display:flex;flex-direction:column;min-height:calc(100dvh - 184px)}
.task-table-scroll{position:relative;max-width:100%;overflow-x:auto;scrollbar-width:none;overscroll-behavior-x:contain}
.task-table-scroll::-webkit-scrollbar{display:none}
.task-table{min-width:900px}
.task-table th:first-child{width:36%}
.task-table th:nth-child(2){width:14%}
.task-table th:nth-child(3){width:14%}
.task-list-title{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-weight:400;color:var(--foreground);text-decoration:none}
.task-list-title:hover{text-decoration:underline;text-underline-offset:3px}
.task-table time{font-size:12px;color:var(--muted-foreground)}
.task-table-empty{padding:24px 12px!important;color:var(--muted-foreground)}
.execution-facts{display:flex;flex-wrap:wrap;gap:16px 32px;margin:0 0 28px;font-size:13px}
.execution-facts>div{display:grid;gap:4px}
.execution-facts dt{color:var(--muted-foreground)}
.execution-facts dd{margin:0}
.task-objective,.task-configuration,.task-instructions,.task-current-progress,.task-results{margin:0 0 var(--section-space);padding:0 0 var(--section-space);border-bottom:1px solid var(--border);min-width:0}
.task-objective .semantic{font-size:16px;line-height:1.75;max-width:72ch}
.task-rule-name{font-size:15px;font-weight:550;margin:0 0 8px}
.task-rule-facts{display:grid;gap:12px;margin:20px 0}
.task-rule-facts>div{display:grid;grid-template-columns:minmax(140px,.8fr) minmax(0,1.4fr);gap:18px}
.task-rule-facts dt{font-size:13px;color:var(--muted-foreground)}
.task-rule-facts dd{font-size:14px;margin:0;overflow-wrap:anywhere}
.task-rule-facts time{font-size:14px;color:var(--foreground);margin:0}
.task-instructions ol{list-style:none;margin:0;padding:0}
.task-instructions li+li{margin-top:18px;padding-top:18px;border-top:1px solid var(--border)}
.task-instructions time{display:block;color:var(--muted-foreground);font-size:12px;margin-top:8px}
.task-scheduled-instructions .semantic{margin-top:12px}
.task-objective-preview{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;overflow-wrap:anywhere;color:var(--muted-foreground);max-width:72ch}
.task-row .task-list-rule{font-size:12px;color:var(--muted-foreground);margin-top:12px}
.task-list-rule time{display:inline;font:inherit;color:inherit;margin:0}
@container task-layout (max-width:760px){.task-rule-facts>div{grid-template-columns:minmax(0,1fr);gap:4px}}
.scheduled-work{margin:28px 0 36px}
.scheduled-work-list{border-top:1px solid var(--border)}
.scheduled-work-row{display:flex;justify-content:space-between;align-items:flex-start;gap:24px;padding:22px 0;border-bottom:1px solid var(--border)}
.scheduled-work-row>div{min-width:0}
.scheduled-work-row>div:first-child{flex:1}
.scheduled-work-row h3{font-size:15px;line-height:1.6;font-weight:550;margin:0 0 8px;white-space:pre-wrap;overflow-wrap:anywhere;max-width:72ch}
.scheduled-work-row .field-help{margin:8px 0 0}
.scheduled-work-row .task-list-rule{font-size:13px;margin:0}
.scheduled-rule-details{margin:10px 0 0}
.scheduled-work-actions{display:flex;flex-wrap:wrap;align-items:center;justify-content:flex-end;gap:12px;max-width:38%;font-size:13px}
.scheduled-work-actions .technical-details{margin:0;font-size:12px;overflow-wrap:anywhere}
.scheduled-work-actions .text-link{min-height:44px;display:inline-flex;align-items:center}
@media(max-width:700px){.scheduled-work-row{flex-direction:column;gap:12px}
.scheduled-work-actions{justify-content:flex-start;max-width:100%;gap:12px}}
.schedule-editor{max-width:680px}
.schedule-editor>label,.schedule-editor>.schedule-field,.schedule-editor>[data-schedule-fields]{display:block;margin-bottom:20px}
.schedule-editor>.schedule-field>label{margin-bottom:0}
.schedule-editor textarea{display:block;width:100%;resize:vertical;min-height:130px;margin-top:8px;font:16px/1.6 var(--font-ui)}
.schedule-editor .schedule-enabled{display:flex;align-items:center;flex-direction:row-reverse;justify-content:space-between;gap:8px;margin:0}
.schedule-editor .schedule-enabled input{width:auto;margin:0}
.schedule-editor>p.field-help{margin:8px 0 24px}
.schedule-editor>.technical-details{margin:24px 0}
.schedule-editor .technical-details>label{display:block;margin-top:16px}
.schedule-editor [data-schedule-fields]{display:none}
.schedule-editor [data-schedule-fields="clock"]{display:block}
.schedule-editor:has([name="frequency"] option[value="once"]:checked) [data-schedule-fields="once"],.schedule-editor:has([name="frequency"] option[value="weekly"]:checked) [data-schedule-fields="weekly"],.schedule-editor:has([name="frequency"] option[value="monthly"]:checked) [data-schedule-fields="monthly"],.schedule-editor:has([name="frequency"] option[value="custom"]:checked) [data-schedule-fields="custom"]{display:block}
.schedule-editor:has([name="frequency"] option[value="custom"]:checked) [data-schedule-fields="clock"]{display:none}
@media(max-width:700px){.schedule-editor .actions{align-items:stretch;flex-direction:column}
.schedule-editor input{font-size:16px}}
.schedule-editor textarea{padding:12px;border:1px solid var(--control-border);border-radius:10px;background:var(--card);color:var(--foreground)}
.needs-attention:has(.attention-heading){margin-bottom:36px}
.attention-heading h2{display:flex;align-items:center;gap:10px;margin-bottom:8px}
.attention-heading .status-pill{font-size:12px;font-weight:500;font-variant-numeric:tabular-nums}
.attention-row{display:flex;align-items:center;justify-content:space-between;gap:24px;padding:20px 0;border-bottom:1px solid var(--border)}
.attention-row>div{min-width:0;max-width:70ch}
.attention-row h3{margin:0 0 6px;font-size:15px;line-height:1.5;overflow-wrap:anywhere}
.attention-row p{margin:0;color:var(--muted-foreground);font-size:14px;line-height:1.6}
.attention-row>.button{flex-shrink:0}
.attention-row .attachment-list{margin-top:12px}
.task-feedback-request{padding:0 0 28px;margin:0 0 28px;border-bottom:1px solid var(--border);scroll-margin-top:100px}
.task-feedback-request:focus-visible{outline:2px solid var(--foreground);outline-offset:8px}
.task-feedback-request h2{margin:0 0 14px}
.feedback-prompt{white-space:pre-wrap;overflow-wrap:anywhere;max-width:70ch;line-height:1.7;margin:0 0 16px}
.task-feedback-form>label,.feedback-status>label{display:block;font-size:14px;font-weight:500;margin:20px 0 8px}
.task-feedback-form textarea,.feedback-status textarea{width:100%;min-height:100px;resize:vertical;padding:12px;font:16px/1.6 var(--font-ui);border:1px solid var(--control-border);border-radius:10px;background:var(--card);color:var(--foreground)}
.task-feedback-form textarea:focus-visible,.feedback-status textarea:focus-visible{outline:2px solid var(--foreground);outline-offset:2px}
.task-feedback-form .field-help{margin:10px 0 18px;max-width:70ch}
.feedback-status:not(:empty){margin:20px 0 28px}
.feedback-status textarea[readonly]{min-height:80px}
@media(max-width:700px){.attention-row{align-items:flex-start;flex-direction:column;gap:14px}
.attention-row>.button{align-self:flex-start}
.task-feedback-form button{min-height:44px}}
.task-configuration h2{display:flex;align-items:center;gap:8px}
.execution-page{max-width:900px;container:execution-layout / inline-size}
.execution-heading{position:relative;padding-bottom:16px;margin-bottom:20px;border-bottom:1px solid var(--border)}
.execution-heading h1{margin:0 0 8px;font-size:18px;line-height:1.5;font-weight:600;overflow-wrap:anywhere}
.execution-summary{display:flex;align-items:center;flex-wrap:wrap;gap:8px 16px;color:var(--muted-foreground);font-size:12px;line-height:1.5}
.execution-summary time{font:inherit;color:inherit}
.execution-trace{margin-left:auto;color:var(--foreground)}
.execution-actions{display:flex;align-items:center;flex-wrap:wrap;gap:8px 20px;margin-top:12px;font-size:12px}
.execution-actions>.control-icon-button{margin-left:auto}
.execution-metadata .execution-actions{margin:8px 0 12px}
.execution-main{min-width:0;max-width:76ch}
.execution-progress>h2{font-size:13px;line-height:1.5;margin:0 0 8px;font-weight:500;color:var(--muted-foreground)}
.execution-empty{margin:0;color:var(--muted-foreground);font-size:14px;line-height:1.7}
.execution-progress{margin:0 0 20px;max-width:76ch}
.execution-progress p{font-size:14px;line-height:1.7;overflow-wrap:anywhere;margin:0}
.execution-side{margin-top:32px;max-width:76ch;font-size:13px}
.execution-side>details{border-top:1px solid var(--border)}
.execution-side summary{font-weight:500;cursor:pointer;min-height:44px;align-content:center}
.execution-count{font-size:12px;font-weight:400;color:var(--muted-foreground);margin-left:6px}
.execution-instructions .semantic{font-size:13px;line-height:1.7;margin:0 0 16px;overflow-wrap:anywhere}
.execution-instructions h3{font-size:13px;margin:16px 0 8px}
.execution-instructions ol{padding-left:18px;margin:0 0 16px}
.execution-history ol{list-style:none;padding:0;margin:0 0 12px}
.execution-history a{display:grid;grid-template-columns:1fr auto;align-items:center;gap:4px 12px;text-decoration:none;padding:8px 0}
.execution-history a[aria-current]{font-weight:600}
.execution-history a:hover>span:first-child{text-decoration:underline}
.execution-history time{grid-column:1/-1;color:var(--muted-foreground);font-size:12px}
.execution-facts{display:grid;gap:8px;margin:0 0 16px;font-size:12px}
.execution-facts>div{display:grid;grid-template-columns:100px minmax(0,1fr);align-items:center;gap:12px}
.execution-facts dd{margin:0;min-width:0}
.execution-facts dt{color:var(--muted-foreground)}
.execution-facts time{font:inherit;color:inherit}
.control-sheet .execution-page{padding:20px 24px;margin:0;max-width:none}
.control-sheet .execution-page>.back-link{display:none}
.task-table tr[data-execution-row]:hover{background:var(--hover)}
@media(max-width:760px){.execution-actions>.text-link{display:inline-flex;align-items:center;min-height:44px}
.control-sheet .execution-page{padding:20px}
.execution-heading{padding-bottom:12px;margin-bottom:20px}
.execution-actions{margin-top:8px}}
.thread{max-width:840px;padding:24px 36px 260px;margin:auto}
.welcome{text-align:center}
.welcome h1{font-family:var(--font-display);font-size:36px;line-height:1.35;letter-spacing:-.02em;margin:0;font-weight:400;text-wrap:balance}
.welcome p{color:var(--muted-foreground);font-size:16px;line-height:1.75;margin:auto;max-width:500px}
.workspace-main:has(.welcome){display:grid;grid-template-columns:minmax(0,1fr);grid-template-rows:minmax(min-content,1fr) auto auto minmax(0,1fr)}
.workspace-main:has(.welcome)>.chat-topbar{align-self:start}
.workspace-main:has(.welcome) .thread{width:100%;margin:0 auto;padding-block:0}
.workspace-main:has(.welcome) .conversation-footer{align-self:start;position:relative;left:auto;margin:0;padding:28px 32px max(24px,env(safe-area-inset-bottom));background:none}
.setup-callout{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:10px 16px;padding:12px 16px;border:1px solid var(--border);border-radius:var(--radius);margin:8px 0 20px}
.setup-callout h1{font-size:var(--text-section);font-weight:600;margin:0}
.setup-callout p{font-size:13px;color:var(--muted-foreground);margin:4px 0 0}
.message,.reply-draft{padding:18px 0;font-size:16px;line-height:1.75;min-width:0;scroll-margin-top:88px}
.message:target{background:var(--muted);outline:8px solid var(--muted);border-radius:8px}
.message.user{margin:18px 0 20px auto;padding:13px 19px;background:var(--muted);border-radius:22px;width:fit-content;max-width:85%}
.message.assistant .semantic,.reply-draft .semantic{font-family:var(--font-display);font-size:16px;line-height:1.75;font-optical-sizing:auto}
.task-delivery .semantic{font-family:var(--font-ui);font-size:14px;line-height:1.6}
.task-delivery .markdown table{font:inherit}
.reply-draft-label{color:var(--muted-foreground);font-size:12px;margin-bottom:4px}
.conversation-footer{position:fixed;bottom:0;left:var(--sidebar-width);right:0;padding:14px 32px 12px;background:var(--background);z-index:6}
.composer{max-width:768px;margin:auto;border:1px solid var(--control-border);background:var(--card);border-radius:18px;padding:10px 12px 6px}
.composer textarea{display:block;width:100%;border:0;resize:none;margin:0;padding:0 3px 4px;background:transparent;color:var(--foreground);font-size:16px;line-height:1.5;min-height:36px;max-height:180px;field-sizing:content;outline:none}
.composer textarea::placeholder{color:var(--muted-foreground)}
.composer-actions{display:flex;align-items:center;justify-content:space-between;gap:12px}
.attachment-controls{display:flex;align-items:center;gap:6px;min-width:0;max-width:70%}
.attachment-picker{position:relative;display:flex;align-items:center;justify-content:center;width:36px;height:36px;flex-shrink:0;color:var(--muted-foreground);border-radius:9px;margin:0;cursor:pointer}
.attachment-picker:hover{background:var(--hover)}
.attachment-picker input{position:absolute;inset:0;width:100%;height:100%;opacity:0;padding:0;margin:0;cursor:pointer}
.attachment-status{font-size:12px;color:var(--muted-foreground);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.composer:focus-within{border-color:var(--focus)}
.composer:has(textarea:focus-visible){outline:0;box-shadow:none}
.attachment-picker:has(input:focus-visible){outline:2px solid var(--focus);outline-offset:2px}
.composer .send-button{position:relative;width:36px;height:36px;min-height:36px;padding:0;border-radius:50%;flex-shrink:0;background:var(--chat-accent);color:#fff;border:0;box-shadow:none}
.composer .send-button:hover{opacity:.85}
.composer .send-button .icon{width:20px;height:20px;stroke-width:1.8}
.composer[data-submitting] .send-button .icon{opacity:0}
.composer[data-submitting] .send-button:after{content:"";position:absolute;inset:10px;border:2px solid var(--muted-foreground);border-top-color:transparent;border-radius:50%;animation:send-wait .9s linear infinite}
@keyframes send-wait{to{transform:rotate(360deg)}}
.composer-feedback{font-size:13px;color:var(--muted-foreground);margin:10px 4px 0}
.composer-feedback:empty{display:none}
.task-context-chip{display:flex;justify-content:space-between;align-items:center;gap:10px;margin:0 4px 12px;padding:6px 9px;font-size:12px;background:var(--muted);border-radius:7px}
.task-context-chip>span{min-width:0;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}
#new-messages{position:fixed;right:36px;bottom:220px;border-radius:20px;z-index:7;font-size:12px}
@media(max-width:760px){.thread{padding:20px 20px 250px}
.welcome h1{font-size:30px}
.welcome p{font-size:15px;max-width:290px}
.workspace-main:has(.welcome) .conversation-footer{padding:24px 12px 40px}
.conversation-footer{left:0;padding:12px 12px max(12px,env(safe-area-inset-bottom))}
.composer{padding:8px 10px 4px}
.message.user{max-width:94%}
.attachment-controls{max-width:80%}
#new-messages{bottom:215px;right:16px}}
.thread{padding-bottom:calc(var(--composer-height,220px) + 24px)}
#new-messages{bottom:calc(var(--composer-height,220px) + 12px);min-height:40px;font-size:13px}
@media(max-width:760px){.composer .send-button,.attachment-picker{width:44px;height:44px;min-height:44px}
.composer-actions{gap:8px}}
.message{scroll-margin-top:176px}
.message,.reply-draft{width:fit-content;max-width:90%;margin:14px 0;padding:14px 18px;border-radius:18px}
.message.assistant,.reply-draft{margin-right:auto;background:var(--muted)}
.message.user{margin-left:auto;background:var(--chat-accent);color:#fff}
.message:has(.approval){width:100%;max-width:100%;padding:0;background:transparent}
.composer textarea{font-size:14px;line-height:1.6}
.agent-processing{display:none;align-items:center;gap:10px;width:fit-content;border-radius:18px;padding:12px 16px;margin:14px 0;background:var(--muted);color:var(--muted-foreground);font-size:12px}
.chat-workspace:has(#workspace-status .working) .agent-processing,.chat-workspace[data-waiting-reply] .agent-processing{display:flex}
.chat-workspace:has(#conversation-draft:not([hidden])) .agent-processing{display:none}
.typing-dots{display:inline-flex;gap:4px}
.typing-dots i{width:5px;height:5px;border-radius:50%;background:currentColor;animation:thinking 1.2s ease-in-out infinite}
.typing-dots i:nth-child(2){animation-delay:.16s}
.typing-dots i:nth-child(3){animation-delay:.32s}
@keyframes thinking{0%,70%,100%{opacity:.35;transform:translateY(0)}35%{opacity:1;transform:translateY(-3px)}}
@media(prefers-reduced-motion:reduce){.typing-dots i{animation:none}}
@media(max-width:760px){.message,.reply-draft{max-width:96%;padding:12px 14px}
.composer textarea{font-size:16px}}
:root{--chat-accent:#B84F2F}
.message.message-split{display:flex;flex-direction:column;gap:14px;width:100%;max-width:100%;padding:0;background:transparent}
.message-bubble{width:fit-content;max-width:90%;padding:14px 18px;border-radius:18px;background:var(--muted);min-width:0}
.message-bubble:has(.intelligent-widget,.answer-table,.openintelligentui-native){width:90%}
.outgoing-status,.outgoing-file{font:12px/1.6 var(--font-ui);margin-top:6px}
.outgoing-status button{min-height:32px;padding:0;background:transparent;color:inherit;text-decoration:underline;border:0}
.outgoing[data-send-state=sending] .outgoing-status:before{content:"";display:inline-block;width:10px;height:10px;margin-right:7px;border:1px solid currentColor;border-right-color:transparent;border-radius:50%;animation:send-wait .9s linear infinite}
@media(prefers-reduced-motion:reduce){.outgoing[data-send-state=sending] .outgoing-status:before{animation:none}}
@media(max-width:760px){.message-bubble{max-width:96%;padding:12px 14px}
.message-bubble:has(.intelligent-widget,.answer-table,.openintelligentui-native){width:96%}}
.message-bubble:has(.openintelligentui-native){width:90%}
@media(max-width:760px){.message-bubble:has(.openintelligentui-native){width:96%}}
.message:has(>.message-time){position:relative;margin-bottom:38px}
.message-time{position:absolute;top:100%;left:0;padding-top:4px;color:var(--muted-foreground);font:12px/1.6 var(--font-ui);white-space:nowrap}
.message.user>.message-time{left:auto;right:0}
.message-time time{border-radius:3px}
.message-time time:focus-visible{outline:2px solid var(--focus);outline-offset:3px}
.message-date{text-align:center;margin:24px 0 18px;color:var(--muted-foreground);font:13px/1.6 var(--font-ui)}
@media(hover:hover) and (pointer:fine){.js .message-time{opacity:0}
.js .message:is(:hover,:focus-within)>.message-time{opacity:1}}
.composer-secondary-actions{display:flex;align-items:center;gap:8px;min-width:0;margin-left:auto;max-width:calc(100% - 48px)}
.composer-model{position:relative;min-width:0;max-width:100%}
.composer-model-error{position:absolute;right:0;bottom:calc(100% + 12px);width:max-content;max-width:min(320px,70vw);padding:8px 12px;background:var(--card);border:1px solid var(--border);border-radius:8px;color:var(--foreground);font:13px/1.6 var(--font-ui)}
#composer-model-form{display:flex;justify-content:flex-end}
#conversation-messages{position:relative}
.message[data-ui-handoff]{position:absolute;inset-inline:0;visibility:hidden;pointer-events:none}

